python - <<'PY'
from PIL import Image
import numpy as np
for d in ['grasp1','probe4','grasp2']:
 for c in ['front','top','oblique']:
  a=np.array(Image.open(f'/app/output/{d}/last/{c}.jpg'))
  yy,xx=np.mgrid[:240,:320]
  if c=='front':roi=(xx>135)&(xx<190)&(yy>87)&(yy<121)
  elif c=='top':roi=(xx>148)&(xx<180)&(yy>90)&(yy<130)
  else:roi=(xx>145)&(xx<190)&(yy>85)&(yy<130)
  mask=(a[:,:,0]>150)&(a[:,:,1]>150)&(a[:,:,2]>150)&(np.max(a,axis=2)-np.min(a,axis=2)<50)&roi
  if mask.sum():print(d,c,mask.sum(),xx[mask].mean(),yy[mask].mean())
PY

